:root {
    /* Default Enterprise Blue Theme */
    --color-primary-50:  #eff6ff;
    --color-primary-100: #dbeafe;
    --color-primary-200: #bfdbfe;
    --color-primary-300: #93c5fd;
    --color-primary-400: #60a5fa;
    --color-primary-500: #3b82f6;
    --color-primary-600: #2563eb;
    --color-primary-700: #1d4ed8;
    --color-primary-800: #1e40af;
    --color-primary-900: #1e3a8a;
    --color-primary-950: #172554;

    --font-sans: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

@theme {
    --color-brand-50: var(--color-primary-50);
    --color-brand-100: var(--color-primary-100);
    --color-brand-200: var(--color-primary-200);
    --color-brand-300: var(--color-primary-300);
    --color-brand-400: var(--color-primary-400);
    --color-brand-500: var(--color-primary-500);
    --color-brand-600: var(--color-primary-600);
    --color-brand-700: var(--color-primary-700);
    --color-brand-800: var(--color-primary-800);
    --color-brand-900: var(--color-primary-900);
    --color-brand-950: var(--color-primary-950);

    --font-sans: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

/* ==========================================================================
   Base
   ========================================================================== */
@layer base {
    html {
        scroll-behavior: smooth;
    }

    body {
        background-color: #f4f7fb;
        color: #0f172a;
        font-family: var(--font-sans);
        -webkit-font-smoothing: antialiased;
        text-rendering: optimizeLegibility;
    }

    [x-cloak] {
        display: none !important;
    }

    ::selection {
        background-color: var(--color-primary-600);
        color: #fff;
    }

    :focus-visible {
        outline: 2px solid var(--color-primary-500);
        outline-offset: 2px;
    }

    * {
        scrollbar-width: thin;
        scrollbar-color: #cbd5e1 transparent;
    }

    ::-webkit-scrollbar {
        width: 8px;
        height: 8px;
    }

    ::-webkit-scrollbar-track {
        background: transparent;
    }

    ::-webkit-scrollbar-thumb {
        background: #cbd5e1;
        border-radius: 999px;
        border: 2px solid transparent;
        background-clip: padding-box;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #94a3b8;
        border: 2px solid transparent;
        background-clip: padding-box;
    }
}

/* ==========================================================================
   Component system
   ========================================================================== */
@layer components {
    /* --- Layout shell ------------------------------------------------------ */
    .app-sidebar {
        background:
            radial-gradient(120% 60% at 0% 0%, color-mix(in srgb, var(--color-primary-500) 18%, transparent) 0%, transparent 60%),
            linear-gradient(180deg, var(--color-primary-950) 0%, #080f1f 100%);
    }

    .sidebar-link {
        @apply relative flex items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] font-semibold text-white/60 transition-all duration-150 hover:bg-white/[0.06] hover:text-white;
    }

    .sidebar-link-active {
        @apply bg-white/[0.1] text-white shadow-[inset_0_1px_0_rgba(255,255,255,0.08)];
    }

    .sidebar-link-active::before {
        content: '';
        position: absolute;
        left: -0.75rem;
        top: 50%;
        height: 1.35rem;
        width: 3px;
        transform: translateY(-50%);
        border-radius: 0 999px 999px 0;
        background: var(--color-primary-400);
        box-shadow: 0 0 12px color-mix(in srgb, var(--color-primary-400) 70%, transparent);
    }

    .app-topbar {
        @apply sticky top-0 z-30 border-b border-slate-200/70 bg-white/80 backdrop-blur-xl;
    }

