/* Tabular Numbers Utility untuk Seluruh Angka Keuangan & Stok */
.num-tabular {
    font-family: var(--font-mono);
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.02em;
}

@keyframes modal-in {
    from {
        opacity: 0;
        transform: translateY(12px) scale(0.98);
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

@keyframes page-in {
    from {
        opacity: 0;
        transform: translateY(4px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Clean Thermal Receipt & Report Print Styles */
@media print {
    /* Sembunyikan elemen navigasi, filter, dan tombol saat cetak */
    .app-sidebar,
    .app-topbar,
    .no-print,
    header,
    nav,
    form {
        display: none !important;
    }

    body {
        background: #fff !important;
    }

    .app-main {
        padding: 0 !important;
        max-width: none !important;
    }

    .card,
    .table-shell {
        border: 0 !important;
        box-shadow: none !important;
        border-radius: 0 !important;
    }

    /* Print receipt styling jika ada #thermal-receipt aktif */
    body:has(#thermal-receipt:not(.hidden)) * {
        visibility: hidden;
    }
    body:has(#thermal-receipt:not(.hidden)) #thermal-receipt,
    body:has(#thermal-receipt:not(.hidden)) #thermal-receipt * {
        visibility: visible;
    }
    body:has(#thermal-receipt:not(.hidden)) #thermal-receipt {
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        border: 0 !important;
    }

    /* Standard A4 Report Margins */
    @page {
        size: A4 portrait;
        margin: 15mm;
    }
}

