import { spawn } from 'node:child_process';
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { setTimeout as sleep } from 'node:timers/promises';

const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const BASE = 'http://127.0.0.1:8000';
const PORT = 9333;
const PROFILE = 'C:\\Users\\HYPE AMD\\AppData\\Local\\Temp\\opencode\\bestco-chrome-profile';
const OUT = 'C:\\Users\\HYPE AMD\\AppData\\Local\\Temp\\opencode\\bestco-shots';

const pages = process.argv.slice(2).length
  ? process.argv.slice(2)
  : ['/dashboard', '/pos', '/transactions', '/inventory', '/inventory/mutations', '/inventory/spoilage', '/piket', '/shift', '/reports', '/settings/theme'];

const WIDTH = Number(process.env.SHOT_WIDTH || 1440);
const HEIGHT = Number(process.env.SHOT_HEIGHT || 900);
const FULL = process.env.SHOT_FULL === '1';

mkdirSync(OUT, { recursive: true });

// --- Login over plain HTTP and grab session cookies ---
async function login() {
  const jar = new Map();
  const store = (res) => {
    const raw = res.headers.getSetCookie?.() ?? [];
    for (const c of raw) {
      const [pair] = c.split(';');
      const idx = pair.indexOf('=');
      jar.set(pair.slice(0, idx), pair.slice(idx + 1));
    }
  };

  let res = await fetch(`${BASE}/login`, { redirect: 'manual' });
  store(res);
  const html = await res.text();
  const token = html.match(/name="_token"\s+value="([^"]+)"/)?.[1];
  if (!token) throw new Error('CSRF token not found');

  const body = new URLSearchParams({ _token: token, login: 'superadmin', password: 'password' });
  res = await fetch(`${BASE}/login`, {
    method: 'POST',
    redirect: 'manual',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      Cookie: [...jar].map(([k, v]) => `${k}=${v}`).join('; '),
    },
    body,
  });
  store(res);

  return [...jar].map(([name, value]) => ({ name, value, domain: '127.0.0.1', path: '/' }));
}

// --- Launch chrome ---
rmSync(PROFILE, { recursive: true, force: true });
const chrome = spawn(CHROME, [
  '--headless=new',
  `--remote-debugging-port=${PORT}`,
  `--user-data-dir=${PROFILE}`,
  '--no-first-run',
  '--no-default-browser-check',
  '--disable-gpu',
  '--hide-scrollbars',
  '--force-device-scale-factor=1',
  `--window-size=${WIDTH},${HEIGHT}`,
  'about:blank',
], { stdio: 'ignore' });

async function cdpTarget() {
  for (let i = 0; i < 60; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
      const list = await res.json();
      const page = list.find((t) => t.type === 'page');
      if (page) return page.webSocketDebuggerUrl;
    } catch {}
    await sleep(250);
  }
  throw new Error('Chrome did not start');
}

const wsUrl = await cdpTarget();
const ws = new WebSocket(wsUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });

let seq = 0;
const pending = new Map();
const events = [];
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
  } else if (msg.method) {
    events.push(msg.method);
  }
};
function send(method, params = {}) {
  const id = ++seq;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}
async function waitFor(method, timeout = 15000) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    const idx = events.indexOf(method);
    if (idx !== -1) { events.splice(0, idx + 1); return; }
    await sleep(100);
  }
}

await send('Page.enable');
await send('Runtime.enable');
await send('Network.enable');
await send('Emulation.setDeviceMetricsOverride', { width: WIDTH, height: HEIGHT, deviceScaleFactor: 1, mobile: false });

const cookies = await login();
await send('Network.setCookies', { cookies });

for (const path of pages) {
  const name = path.replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '') || 'root';
  events.length = 0;
  await send('Page.navigate', { url: `${BASE}${path}` });
  await waitFor('Page.loadEventFired');
  await sleep(600); // allow Alpine + fonts to settle

  const shot = await send('Page.captureScreenshot', {
    format: 'png',
    captureBeyondViewport: FULL,
    ...(FULL ? {} : { clip: undefined }),
  });

  // For full page, get content size and capture with clip.
  let data = shot.data;
  if (FULL) {
    const metrics = await send('Page.getLayoutMetrics');
    const size = metrics.cssContentSize;
    const full = await send('Page.captureScreenshot', {
      format: 'png',
      captureBeyondViewport: true,
      clip: { x: 0, y: 0, width: size.width, height: size.height, scale: 1 },
    });
    data = full.data;
  }

  const file = `${OUT}\\${name}.png`;
  writeFileSync(file, Buffer.from(data, 'base64'));

  const title = await send('Runtime.evaluate', { expression: 'document.title', returnByValue: true });
  console.log(`${file}\t${title.result.value}`);
}

ws.close();
chrome.kill();
process.exit(0);

