(() => {
  const modal = [...document.querySelectorAll('div')].find(d => d.className.includes('modal-card') && d.offsetParent !== null);
  const inputs = [...document.querySelectorAll('input, select, button')].map(el => {
    const attrs = [...el.attributes].filter(a => a.name.startsWith('wire:'));
    return attrs.length ? { tag: el.tagName, type: el.type, value: el.value, text: (el.innerText||'').trim().slice(0,30), attrs: Object.fromEntries(attrs.map(a=>[a.name,a.value])) } : null;
  }).filter(Boolean);
  return { modalText: modal?.innerText.slice(0, 1000), inputs };
})()

