import { chromium } from 'playwright';
import fs from 'node:fs';

const base = 'http://127.0.0.1:8000';
const outDir = 'C:/Users/HYPE AMD/AppData/Local/Temp/opencode/bestco-qa/shots';
fs.mkdirSync(outDir, { recursive: true });

const pages = [
  ['dashboard', '/dashboard'],
  ['pos', '/pos'],
  ['transactions', '/transactions'],
  ['inventory', '/inventory'],
  ['mutations', '/inventory/mutations'],
  ['spoilage', '/inventory/spoilage'],
  ['piket', '/piket'],
  ['shift', '/shift'],
  ['reports-bku', '/reports?tab=bku'],
  ['reports-income', '/reports?tab=income_statement'],
  ['theme', '/settings/theme'],
];

const browser = await chromium.launch();
const summary = [];

for (const [label, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
  const context = await browser.newContext({ viewport: { width, height }, deviceScaleFactor: 1 });
  const page = await context.newPage();
  const errors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', (err) => errors.push('pageerror: ' + err.message));

  await page.goto(base + '/login', { waitUntil: 'networkidle' });
  if (!page.url().includes('/dashboard')) {
    await page.fill('input[name="login"]', 'superadmin');
    await page.fill('input[name="password"]', 'password');
    await Promise.all([page.waitForURL('**/dashboard'), page.click('button[type="submit"]')]);
  }

  for (const [name, path] of pages) {
    errors.length = 0;
    await page.goto(base + path, { waitUntil: 'networkidle' });
    await page.waitForTimeout(300);
    const metrics = await page.evaluate(() => ({
      scrollWidth: document.documentElement.scrollWidth,
      innerWidth: window.innerWidth,
      bodyWidth: document.body.scrollWidth,
    }));
    const file = `${outDir}/${label}-${name}.png`;
    await page.screenshot({ path: file, fullPage: true });
    summary.push({
      viewport: label,
      page: name,
      url: page.url(),
      overflowX: Math.max(metrics.scrollWidth, metrics.bodyWidth) - metrics.innerWidth,
      errors: [...errors],
      file,
    });
  }

  await context.close();
}

await browser.close();
console.log(JSON.stringify(summary, null, 2));

