### 10. ColorPaletteGenerator implementation details

Let's write the file.

```
<?php

declare(strict_types=1);

namespace App\Services\Theme;

use InvalidArgumentException;

final class ColorPaletteGenerator
{
    private const SHADE_LIGHTNESS = [
        50 => 0.970,
        100 => 0.935,
        200 => 0.885,
        300 => 0.810,
        400 => 0.705,
        500 => 0.625,
        600 => 0.550,
        700 => 0.490,
        800 => 0.430,
        900 => 0.380,
        950 => 0.280,
    ];

    private const SHADE_CHROMA = [
        50 => 0.12,
        100 => 0.24,
        200 => 0.44,
        300 => 0.66,
        400 => 0.86,
        500 => 0.98,
        600 => 1.00,
        700 => 0.96,
        800 => 0.88,
        900 => 0.80,
        950 => 0.60,
    ];

    /**
     * @return array<string, string>
     */
    public function generate(string $color): array
    {
        [$red, $green, $blue] = $this->parseHex($color);
        [$lightness, $chroma, $hue] = $this->rgbToOklch($red, $green, $blue);

        // Keep some chroma for near-gray inputs so the ramp stays readable.
        $chroma = max($chroma, 0.0);

        $palette = [];
        foreach (self::SHADE_LIGHTNESS as $shade => $targetLightness) {
            $targetChroma = $chroma * self::SHADE_CHROMA[$shade];
            $palette['--color-primary-' . $shade] = $this->oklchToHex($targetLightness, $targetChroma, $hue);
        }

        return $palette;
    }

    public function normalize(string $color): string
    {
        [$red, $green, $blue] = $this->parseHex($color);
        return sprintf('#%02x%02x%02x', $red, $green, $blue);
    }

    /**
     * @return array{0: int, 1: int, 2: int}
     */
    private function parseHex(string $color): array
    {
        $hex = ltrim(trim($color), '#');
        if (preg_match('/^[0-9a-f]{3}$/i', $hex) === 1) {
            $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
        }
        if (preg_match('/^[0-9a-f]{6}$/i', $hex) !== 1) {
            throw new InvalidArgumentException('Kode warna harus berupa hex 3 atau 6 digit.');
        }
        return [
            hexdec(substr($hex, 0, 2)),
            hexdec(substr($hex, 2, 2)),
            hexdec(substr($hex, 4, 2)),
        ];
    }

    /**
     * @return array{0: float, 1: float, 2: float}
     */
    private function rgbToOklch(int $red, int $green, int $blue): array
    {
        $r = $this->srgbToLinear($red / 255);
        $g = $this->srgbToLinear($green / 255);
        $b = $this->srgbToLinear($blue / 255);

        $l = 0.4122214708 * $r + 0.5363325363 * $g + 0.0514459929 * $b;
        $m = 0.2119034982 * $r + 0.6806995451 * $g + 0.1073969566 * $b;
        $s = 0.0883024619 * $r + 0.2817188376 * $g + 0.6299787005 * $b;

        $l_ = $l ** (1 / 3);
        $m_ = $m ** (1 / 3);
        $s_ = $s ** (1 / 3);

        $okL = 0.2104542553 * $l_ + 0.7936177850 * $m_ - 0.0040720468 * $s_;
        $okA = 1.9779984951 * $l_ - 2.4285922050 * $m_ + 0.4505937099 * $s_;
        $okB = 0.0259040371 * $l_ + 0.7827717662 * $m_ - 0.8086757660 * $s_;

        $chroma = sqrt($okA ** 2 + $okB ** 2);
        $hue = rad2deg(atan2($okB, $okA));
        if ($hue < 0) {
            $hue += 360;
        }

        return [$okL, $chroma, $hue];
    }

    private function oklchToHex(float $lightness, float $chroma, float $hue): string
    {
        $lightness = min(1.0, max(0.0, $lightness));
        $chroma = max(0.0, $chroma);

        for ($attempt = 0; $attempt < 32; $attempt++) {
            $radians = deg2rad($hue);
            $okA = $chroma * cos($radians);
            $okB = $chroma * sin($radians);

            [$r, $g, $b] = $this->oklabToSrgb($lightness, $okA, $okB);

            if ($r >= -0.0001 && $r <= 1.0001 && $g >= -0.0001 && $g <= 1.0001 && $b >= -0.0001 && $b <= 1.0001) {
                return sprintf(
                    '#%02x%02x%02x',
                    (int) round($this->clamp01($r) * 255),
                    (int) round($this->clamp01($g) * 255),
                    (int) round($this->clamp01($b) * 255)
                );
            }

            $chroma *= 0.9;
        }

        [$r, $g, $b] = $this->oklabToSrgb($lightness, 0.0, 0.0);

        return sprintf(
            '#%02x%02x%02x',
            (int) round($this->clamp01($r) * 255),
            (int) round($this->clamp01($g) * 255),
            (int) round($this->clamp01($b) * 255)
        );
    }

    /**
     * @return array{0: float, 1: float, 2: float}
     */
    private function oklabToSrgb(float $lightness, float $okA, float $okB): array
    {
        $l_ = $lightness + 0.3963377774 * $okA + 0.2158037573 * $okB;
        $m_ = $lightness - 0.1055613458 * $okA - 0.0638541728 * $okB;
        $s_ = $lightness - 0.0894841775 * $okA - 1.2914855480 * $okB;

        $l = $l_ ** 3;
        $m = $m_ ** 3;
        $s = $s_ ** 3;

        $r = 4.0767416621 * $l - 3.3077115913 * $m + 0.2309699292 * $s;
        $g = -1.2684380046 * $l + 2.6097574011 * $m - 0.3413193965 * $s;
        $b = -0.0041960863 * $l - 0.7034186147 * $m + 1.7076147010 * $s;

        return [
            $this->linearToSrgb($r),
            $this->linearToSrgb($g),
            $this->linearToSrgb($b),
        ];
    }

    private function srgbToLinear(float $channel): float
    {
        return $channel <= 0.04045
            ? $channel / 12.92
            : (($channel + 0.055) / 1.055) ** 2.4;
    }

    private function linearToSrgb(float $channel): float
    {
        return $channel <= 0.0031308
            ? 12.92 * $channel
            : 1.055 * ($channel ** (1 / 2.4)) - 0.055;
    }

    private function clamp01(float $value): float
    {
        return min(1.0, max(0.0, $value));
    }
}
```

