import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const [url, widthArg, heightArg, outPath] = process.argv.slice(2);
const width = Number(widthArg || 390);
const height = Number(heightArg || 844);
const chrome = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const port = 9333;
const profile = `C:\\Users\\HYPE AMD\\AppData\\Local\\Temp\\opencode\\cdp-profile-${Date.now()}`;

const proc = spawn(chrome, [
  '--headless=new',
  '--disable-gpu',
  '--hide-scrollbars',
  `--remote-debugging-port=${port}`,
  `--user-data-dir=${profile}`,
  '--no-first-run',
  '--no-default-browser-check',
  'about:blank',
], { stdio: 'ignore' });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function getJson(path) {
  const res = await fetch(`http://127.0.0.1:${port}${path}`);
  if (!res.ok) throw new Error(`${path}: ${res.status}`);
  return res.json();
}

try {
  let version;
  for (let i = 0; i < 60; i += 1) {
    try {
      version = await getJson('/json/version');
      break;
    } catch {
      await sleep(250);
    }
  }
  if (!version) throw new Error('Chrome did not start');

  const ws = new WebSocket(version.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, { once: true });
    ws.addEventListener('error', reject, { once: true });
  });

  let nextId = 1;
  const pending = new Map();
  ws.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    }
  });
  const send = (method, params = {}, sessionId) => new Promise((resolve, reject) => {
    const id = nextId++;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params, ...(sessionId ? { sessionId } : {}) }));
  });

  const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
  const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });

  await send('Page.enable', {}, sessionId);
  await send('Runtime.enable', {}, sessionId);
  await send('Emulation.setDeviceMetricsOverride', {
    width,
    height,
    deviceScaleFactor: 1,
    mobile: width < 768,
    screenWidth: width,
    screenHeight: height,
  }, sessionId);

  const loaded = new Promise((resolve) => {
    const handler = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.sessionId === sessionId && msg.method === 'Page.loadEventFired') resolve();
    };
    ws.addEventListener('message', handler);
  });

  await send('Page.navigate', { url }, sessionId);
  await Promise.race([loaded, sleep(10000)]);
  await sleep(1200);

  const metrics = await send('Runtime.evaluate', {
    expression: `JSON.stringify({ innerWidth, innerHeight, dpr: devicePixelRatio, scrollWidth: document.documentElement.scrollWidth, clientWidth: document.documentElement.clientWidth, bodyScrollWidth: document.body.scrollWidth, overflow: document.documentElement.scrollWidth > document.documentElement.clientWidth })`,
    returnByValue: true,
  }, sessionId);

  const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false }, sessionId);
  writeFileSync(outPath, Buffer.from(shot.data, 'base64'));
  console.log(metrics.result.value);
  console.log(outPath);
  ws.close();
} finally {
  proc.kill();
}

