    if (e.key === 'e' || e.key === 'E' || e.key === '+' || e.key === ',' || e.key === ';' ... ) e.preventDefault();
    if (!allowDecimal && e.key === '.') e.preventDefault();
    if (!allowNegative && e.key === '-') e.preventDefault();
