Pseudo:

```js
const SELECTOR = 'input[type="number"], input[data-currency], input[data-quantity]';

function isDecimalAllowed(input) {
  if (input.dataset.allowDecimal === 'true') return true;
  if (input.dataset.allowDecimal === 'false') return false;
  if (input.hasAttribute('data-currency')) return false;
  const step = input.getAttribute('step') || '';
  return step.includes('.');
}

function sanitize(raw, allowDecimal) {
  let value = String(raw ?? '');
  // keep digits and dots
  value = value.replace(allowDecimal ? /[^\d.]/g : /[^\d]/g, '');
  if (allowDecimal) {
    const parts = value.split('.');
    value = parts.shift() + (parts.length ? '.' + parts.join('') : '');
  }
  // strip leading zeros (but keep "0" and "0.x")
  if (allowDecimal) {
    value = value.replace(/^0+(?=\d)/, '');
  } else {
    value = value.replace(/^0+(?=\d)/, '');
  }
  // cap digits
  const [intPart, decPart] = value.split('.');
  const maxInt = 15;
  const maxDec = 4;
  let out = intPart.slice(0, maxInt);
  if (allowDecimal && decPart !== undefined) out += '.' + decPart.slice(0, maxDec);
  return out;
}
```

