```js
function guard(input) {
  if (input.dataset.numericGuard === '1') return;
  input.dataset.numericGuard = '1';
  const allowDecimal = isDecimalAllowed(input);
  if (input.type === 'number') {
    input.type = 'text';
  }
  input.inputMode = allowDecimal ? 'decimal' : 'numeric';
  input.autocomplete = 'off';
  input.spellcheck = false;
  input.setAttribute('pattern', allowDecimal ? '[0-9]*[.,]?[0-9]*' : '[0-9]*');
  input.maxLength = allowDecimal ? 20 : 15; // maybe
  const clean = (v) => sanitize(v, allowDecimal);
  const apply = () => {
    const cleaned = clean(input.value);
    if (cleaned !== input.value) {
      const start = input.selectionStart ?? input.value.length;
      const before = input.value;
      input.value = cleaned;
      const delta = cleaned.length - before.length;
      try { input.setSelectionRange(Math.max(0, start + delta), Math.max(0, start + delta)); } catch {}
    }
  };
  input.addEventListener('beforeinput', (e) => {
    if (e.data && clean(e.data) !== e.data) e.preventDefault();
  });
  input.addEventListener('keydown', (e) => {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    if (e.key.length === 1) {
      const ok = /[0-9]/.test(e.key) || (allowDecimal && e.key === '.');
      if (!ok) e.preventDefault();
    }
  });
  input.addEventListener('paste', (e) => {
    const text = (e.clipboardData || window.clipboardData)?.getData('text') ?? '';
    const cleaned = clean(text);
    if (cleaned !== text) {
      e.preventDefault();
      const start = input.selectionStart ?? input.value.length;
      const end = input.selectionEnd ?? start;
      input.setRangeText(cleaned, start, end, 'end');
      input.dispatchEvent(new Event('input', { bubbles: true }));
    }
  });
  input.addEventListener('input', apply);
  input.addEventListener('blur', () => {
    if (input.value.endsWith('.')) input.value = input.value.slice(0, -1);
    if (input.value === '') return;
  });
  // initial cleanup? Don't alter server values like "0.0000" maybe fine.
}
