251:         $allowedRoles = $this->manageableRoleValues($actor);
252:         $studentProfile = $user?->studentProfile;
253:         $requestedRole = (string) $request->input('role_type');
254:         $isStudent = $requestedRole === UserRole::PIKET_SISWA->value;
255:         $requiresPin = in_array($requestedRole, [
256:             UserRole::SUPERADMIN->value,
257:             UserRole::ADMIN->value,
258:             UserRole::PIKET_GURU->value,
259:         ], true);
260:         $pinRequired = $requiresPin && ($user === null || $user->pin_code === null);
261: 
262:         return [
263:             'name' => ['required', 'string', 'max:150'],
264:             'username' => [
