288:                 : ['required', 'string', 'min:8', 'confirmed'],
289:             'pin_code' => ['nullable', 'digits:6', Rule::requiredIf($pinRequired)],
290:             'school_class_id' => [
291:                 'nullable',
292:                 'exists:school_classes,id',
