import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const width = Number(process.argv[2] || 1440);
const height = Number(process.argv[3] || 900);
const outPath = process.argv[4] || 'C:\\Users\\HYPE AMD\\AppData\\Local\\Temp\\opencode\\bestco-users-desktop.png';
const chrome = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const port = 9335;
const profile = `C:\\Users\\HYPE AMD\\AppData\\Local\\Temp\\opencode\\cdp-users-${Date.now()}`;

const proc = spawn(chrome, [
  '--headless=new', '--disable-gpu', '--hide-scrollbars',
  `--remote-debugging-port=${port}`, `--user-data-dir=${profile}`,
  '--no-first-run', '--no-default-browser-check', 'about:blank',
], { stdio: 'ignore' });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function getJson(path) {
  const res = await fetch(`http://127.0.0.1:${port}${path}`);
  if (!res.ok) throw new Error(`${path}: ${res.status}`);
  return res.json();
}

try {
  let version;
  for (let i = 0; i < 60; i += 1) {
    try { version = await getJson('/json/version'); break; } catch { await sleep(250); }
  }
  if (!version) throw new Error('Chrome did not start');

  const ws = new WebSocket(version.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, { once: true });
    ws.addEventListener('error', reject, { once: true });
  });

  let nextId = 1;
  const pending = new Map();
  const waiters = new Map();
  ws.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    }
    if (msg.method && waiters.has(msg.method)) {
      for (const resolve of waiters.get(msg.method)) resolve(msg.params);
      waiters.delete(msg.method);
    }
  });
  const send = (method, params = {}, sessionId) => new Promise((resolve, reject) => {
    const id = nextId++;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params, ...(sessionId ? { sessionId } : {}) }));
  });
  const waitFor = (method, timeout = 10000) => new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`timeout ${method}`)), timeout);
    const list = waiters.get(method) || [];
    list.push((params) => { clearTimeout(timer); resolve(params); });
    waiters.set(method, list);
  });

  const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
  const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });
  await send('Page.enable', {}, sessionId);
  await send('Runtime.enable', {}, sessionId);
  await send('Emulation.setDeviceMetricsOverride', {
    width, height, deviceScaleFactor: 1, mobile: false,
    screenWidth: width, screenHeight: height,
  }, sessionId);

  const load1 = waitFor('Page.loadEventFired');
  await send('Page.navigate', { url: 'http://127.0.0.1:8000/login' }, sessionId);
  await load1;
  await sleep(400);

  const load2 = waitFor('Page.loadEventFired');
  await send('Runtime.evaluate', {
    expression: `(() => {
      const login = document.querySelector('#login');
      const pass = document.querySelector('#password');
      if (!login || !pass) return false;
      login.value = 'superadmin';
      pass.value = 'password';
      login.closest('form').submit();
      return true;
    })()`,
    returnByValue: true,
  }, sessionId);
  await load2;
  await sleep(1200);

  const load3 = waitFor('Page.loadEventFired');
  await send('Page.navigate', { url: 'http://127.0.0.1:8000/users' }, sessionId);
  await load3;
  await sleep(600);

  const metrics = await send('Runtime.evaluate', {
    expression: `(() => {
      const wrap = document.querySelector('.table-wrap');
      const actions = [...document.querySelectorAll('a[href*="/edit"]')];
      const last = actions[actions.length - 1]?.getBoundingClientRect();
      const headers = [...document.querySelectorAll('.data-table thead th')];
      return {
        url: location.href,
        viewport: innerWidth + 'x' + innerHeight,
        pageScrollable: document.documentElement.scrollHeight > document.documentElement.clientHeight,
        rows: document.querySelectorAll('.data-table tbody tr').length,
        table: wrap ? { clientWidth: wrap.clientWidth, scrollWidth: wrap.scrollWidth, scrollable: wrap.scrollWidth > wrap.clientWidth } : null,
        lastAction: last ? { right: Math.round(last.right), visible: last.right <= innerWidth } : null,
        headers: headers.map(th => ({ text: th.innerText, display: getComputedStyle(th).display })),
        sidebar: (() => { const r = document.querySelector('aside.app-sidebar')?.getBoundingClientRect(); return r ? { left: Math.round(r.left), width: Math.round(r.width) } : null; })(),
        dialogTransform: getComputedStyle(document.querySelector('.page-enter')).transform,
      };
    })()`,
    returnByValue: true,
  }, sessionId);
  console.log(metrics.result.value);

  const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false }, sessionId);
  writeFileSync(outPath, Buffer.from(shot.data, 'base64'));
  console.log(outPath);
  ws.close();
} finally {
  proc.kill();
}

