299:                 Rule::requiredIf($isStudent),
300:                 Rule::unique('student_profiles', 'nis')->ignore($studentProfile?->id),
301:             ],
302:             'phone' => ['nullable', 'string', 'max:20', 'regex:/^[0-9+()\s-]*$/'],
303:         ];
304:     }
