  tabID,
  script: `(async () => {
    await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
    const sel = document.querySelector('#role_type');
    const pin = document.querySelector('#pin_code');
    const studentCard = () => document.querySelector('#nis')?.closest('.card');
    const pinWrap = () => pin?.closest('div');
    const visible = el => !!el && getComputedStyle(el).display !== 'none';

    const initial = {
      role: sel?.value,
      roles: [...sel.options].map(o => o.value),
      studentVisible: visible(studentCard()),
      pinVisible: visible(pinWrap()),
      pinType: pin?.type,
      pinInputmode: pin?.inputMode,
      pinMaxlength: pin?.getAttribute('maxlength'),
      passwordRequired: document.querySelector('#password')?.required,
    };

    sel.value = 'piket_siswa';
    sel.dispatchEvent(new Event('change', { bubbles: true }));
    await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
    const asStudent = { studentVisible: visible(studentCard()), pinVisible: visible(pinWrap()) };

    sel.value = 'piket_guru';
    sel.dispatchEvent(new Event('change', { bubbles: true }));
    await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
    const asTeacher = { studentVisible: visible(studentCard()), pinVisible: visible(pinWrap()) };

    pin.focus();
    pin.value = '12ab34';
    pin.dispatchEvent(new Event('input', { bubbles: true }));
    const letter = new KeyboardEvent('keydown', { key: 'a', bubbles: true, cancelable: true });
    const dash = new KeyboardEvent('keydown', { key: '-', bubbles: true, cancelable: true });
    const comma = new KeyboardEvent('keydown', { key: ',', bubbles: true, cancelable: true });
    pin.dispatchEvent(letter); pin.dispatchEvent(dash); pin.dispatchEvent(comma);

    return {
      initial,
      asStudent,
      asTeacher,
      pinValue: pin.value,
      letterBlocked: letter.defaultPrevented,
      dashBlocked: dash.defaultPrevented,
      commaBlocked: comma.defaultPrevented,
      xOverflow: document.documentElement.scrollWidth > innerWidth,
    };
  })()`
});
const shot = await tools.browser.screenshot({ tabID, fullPage: false });
return { info: info.value, shot };

