(async () => {
    await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
    const buttons = [...document.querySelectorAll('button')].filter(b => b.textContent.trim() === 'Nonaktifkan' && !b.disabled);
    buttons[buttons.length - 1]?.click();
    await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(() => requestAnimationFrame(r))));
    const backdrops = [...document.querySelectorAll('div')].filter(d => d.className.includes('bg-slate-950/65'));
    const backdrop = backdrops.find(d => getComputedStyle(d).display !== 'none');
    const card = backdrop?.querySelector('.rounded-2xl');
    const br = backdrop?.getBoundingClientRect();
    const cr = card?.getBoundingClientRect();
    return {
      available: buttons.length,
      backdrop: br ? {x:Math.round(br.x), y:Math.round(br.y), w:Math.round(br.width), h:Math.round(br.height)} : null,
      card: cr ? {x:Math.round(cr.x), y:Math.round(cr.y), w:Math.round(cr.width), h:Math.round(cr.height)} : null,
      viewport: innerWidth + 'x' + innerHeight,
      centered: !!(br && cr) && Math.abs((cr.x + cr.width / 2) - (br.x + br.width / 2)) < 2 && Math.abs((cr.y + cr.height / 2) - (br.y + br.height / 2)) < 2,
      cardOpacity: card ? getComputedStyle(card).opacity : null,
      wrapperZ: (() => { const w = document.querySelector('[x-data="bestcoDialogComponent()"]'); return w ? getComputedStyle(w).zIndex : null; })(),
      pageEnterTransform: getComputedStyle(document.querySelector('.page-enter')).transform,
      text: card?.innerText?.slice(0, 140),
    };
  })()

