242:                     $this->cart[$key]['final_unit_price'] = (float) $pricing['final_unit_price'];
243:                     $this->cart[$key]['tier_discount_per_unit'] = (float) $pricing['tier_discount_per_unit'];
244:                     $this->cart[$key]['tier_discount_total'] = (float) $pricing['line_tier_discount_total'];
245:                     $this->cart[$key]['subtotal_gross'] = (float) $pricing['line_subtotal_gross'];
246:                     $this->cart[$key]['subtotal_net'] = (float) bcsub($pricing['line_net_before_manual'], $manualDiscount, 4);
247:                 }
248:             } else {
249:                 $gross = bcmul($qty, (string) $item['base_price'], 4);
250:                 $net = bcsub($gross, $manualDiscount, 4);
251:                 $this->cart[$key]['subtotal_gross'] = (float) $gross;
252:                 $this->cart[$key]['subtotal_net'] = (float) $net;
