19:      * Setiap baris debit/kredit asli dibalik, dan jurnal asli ditandai is_reversed.
20:      */
21:     public function execute(JournalEntry $originalJournal, string $reversingJournalNumber, User $createdBy): JournalEntry
22:     {
23:         return DB::transaction(function () use ($originalJournal, $reversingJournalNumber, $createdBy): JournalEntry {
24:             // Tandai jurnal asli sebagai reversed.
25:             $originalJournal->update(['is_reversed' => true]);
26: 
27:             // Buat baris jurnal pembalik: debit menjadi kredit dan sebaliknya.
28:             $lines = [];
29:             $totalDebit = '0.0000';
30:             $totalCredit = '0.0000';
31: 
32:             foreach ($originalJournal->items as $item) {
33:                 $reversedDebit = $item->credit;
34:                 $reversedCredit = $item->debit;
35: 
36:                 $totalDebit = bcadd($totalDebit, $reversedDebit, 4);
37:                 $totalCredit = bcadd($totalCredit, $reversedCredit, 4);
38: 
39:                 $lines[] = new JournalLineData(
40:                     chartOfAccountCode: $item->chartOfAccount->account_code,
41:                     debit: $reversedDebit,
42:                     credit: $reversedCredit,
43:                     lineDescription: 'REVERSING: ' . ($item->line_description ?? $originalJournal->description),
44:                 );
45:             }
46: 
47:             $data = new JournalEntryData(
48:                 journalNumber: $reversingJournalNumber,
49:                 accountingPeriodId: (string) $originalJournal->accounting_period_id,
50:                 posShiftId: $originalJournal->pos_shift_id ? (string) $originalJournal->pos_shift_id : null,
51:                 entryDate: Carbon::now(),
52:                 journalType: JournalType::REVERSING,
53:                 referenceType: $originalJournal->reference_type,
54:                 referenceId: $originalJournal->reference_id,
55:                 description: 'Pembalikan jurnal ' . $originalJournal->journal_number . ': ' . $originalJournal->description,
56:                 lines: $lines,
57:                 createdByUserId: (string) $createdBy->getKey(),
58:                 reversedByJournalId: null,
59:             );
