56:             $minAlert = number_format((float) ($data['min_stock_alert'] ?? 5), 4, '.', '');
57:             $initialStock = number_format((float) ($data['initial_stock'] ?? 0), 4, '.', '');
58: 
59:             // Otomatisasi pemetaan akun COA
60:             if ($inventoryType === InventoryType::RETAIL) {
61:                 $invCoa = ChartOfAccount::where('account_code', '1-1301')->firstOrFail(); // Persediaan Barang Dagang
62:                 $cogsCoa = ChartOfAccount::where('account_code', '5-1101')->firstOrFail(); // HPP Barang Dagang
63:             } else {
64:                 $invCoa = ChartOfAccount::where('account_code', '1-1302')->firstOrFail(); // Persediaan Bahan Baku Jasa
65:                 $cogsCoa = ChartOfAccount::where('account_code', '5-2101')->firstOrFail(); // HPP Bahan Baku Jasa
66:             }
67: 
68:             // Generate SKU jika tidak diisi
69:             $sku = trim((string) ($data['sku'] ?? ''));
70:             if ($sku === '') {
71:                 $prefix = $inventoryType === InventoryType::RETAIL ? 'ATK' : 'RAW';
72:                 $slug = strtoupper((string) Str::slug(substr($data['name'], 0, 12)));
73:                 $slug = preg_replace('/[^A-Z0-9]/', '', $slug) ?: 'ITEM';
74:                 $sku = "{$prefix}-{$slug}-" . strtoupper($unit->code);
