78:                     $sku = "{$baseSku}-{$counter}";
79:                     $counter++;
80:                 }
81:             } else {
82:                 if (Product::where('sku', $sku)->exists()) {
83:                     throw new InvalidArgumentException("SKU {$sku} sudah terdaftar.");
