130:                     accountingPeriodId: (string) ($period?->getKey() ?? ''),
131:                     posShiftId: null,
132:                     entryDate: Carbon::now(),
133:                     journalType: JournalType::PURCHASE,
134:                     referenceType: 'App\Models\Product',
135:                     referenceId: $product->id,
136:                     description: "Saldo awal produk baru {$product->name} ({$initialStock} {$unit->code} @ Rp " . number_format((float) $avgCost, 0, ',', '.') . ")",
137:                     lines: [
