25:     /**
26:      * Catat barang rusak / gagal produksi, potong stok bahan baku, dan posting jurnal beban kerusakan.
27:      */
28:     public function execute(SpoilageData $data): SpoilageLog
29:     {
30:         return DB::transaction(function () use ($data): SpoilageLog {
31:             $posShift = PosShift::findOrFail($data->posShiftId);
32: 
33:             // Hitung total biaya kerusakan dan kumpulkan item yang terbuang.
34:             $items = [];
35:             $totalCost = '0.0000';
36: 
37:             if ($data->spoilageSource === 'SERVICE_PRODUCTION' && $data->serviceId) {
38:                 $serviceBoms = ServiceBom::where('service_id', $data->serviceId)
39:                     ->where('is_required', true)
40:                     ->get();
41: 
42:                 foreach ($serviceBoms as $bom) {
43:                     $rawMaterial = Product::where('id', $bom->raw_material_product_id)
44:                         ->lockForUpdate()
45:                         ->firstOrFail();
46: 
47:                     $qtyWasted = bcmul($data->failedOutputQty, (string) $bom->consumption_qty, 4);
48:                     $unitCost = (string) $rawMaterial->average_cost;
49:                     $subtotal = bcmul($qtyWasted, $unitCost, 4);
50: 
51:                     // Verifikasi stok mencukupi.
52:                     if (bccomp((string) $rawMaterial->current_stock, $qtyWasted, 4) === -1) {
53:                         throw new \DomainException(
54:                             'Stok bahan baku tidak mencukupi untuk pencatatan kerusakan: ' .
55:                             $rawMaterial->name . ' (tersedia: ' . $rawMaterial->current_stock . ', dibutuhkan: ' . $qtyWasted . ')'
56:                         );
57:                     }
58: 
59:                     // Potong stok bahan baku.
60:                     $balanceBefore = (string) $rawMaterial->current_stock;
61:                     $rawMaterial->update([
62:                         'current_stock' => bcsub($balanceBefore, $qtyWasted, 4),
63:                     ]);
64: 
65:                     $totalCost = bcadd($totalCost, $subtotal, 4);
66: 
67:                     $items[] = [
68:                         'product' => $rawMaterial,
69:                         'qty_wasted' => $qtyWasted,
70:                         'unit_cost' => $unitCost,
71:                         'subtotal' => $subtotal,
72:                         'balance_before' => $balanceBefore,
73:                         'balance_after' => bcsub($balanceBefore, $qtyWasted, 4),
74:                     ];
75:                 }
76:             } elseif (!empty($data->directItems)) {
77:                 foreach ($data->directItems as $directItem) {
78:                     $product = Product::where('id', $directItem['product_id'])
79:                         ->lockForUpdate()
80:                         ->firstOrFail();
81: 
82:                     $qtyWasted = $directItem['qty_wasted'];
83:                     $unitCost = $directItem['unit_cost'];
84:                     $subtotal = bcmul($qtyWasted, $unitCost, 4);
85: 
86:                     if (bccomp((string) $product->current_stock, $qtyWasted, 4) === -1) {
87:                         throw new \DomainException('Stok tidak mencukupi untuk ' . $product->name);
88:                     }
89: 
90:                     $balanceBefore = (string) $product->current_stock;
91:                     $product->update([
92:                         'current_stock' => bcsub($balanceBefore, $qtyWasted, 4),
93:                     ]);
94: 
95:                     $totalCost = bcadd($totalCost, $subtotal, 4);
96: 
97:                     $items[] = [
98:                         'product' => $product,
99:                         'qty_wasted' => $qtyWasted,
100:                         'unit_cost' => $unitCost,
101:                         'subtotal' => $subtotal,
102:                         'balance_before' => $balanceBefore,
103:                         'balance_after' => bcsub($balanceBefore, $qtyWasted, 4),
104:                     ];
105:                 }
106:             }
107: 
108:             // Buat spoilage_log.
109:             $spoilageNumber = 'SPL-' . Carbon::now()->format('Ymd') . '-' .
110:                 str_pad((string) (SpoilageLog::count() + 1), 4, '0', STR_PAD_LEFT);
111: 
112:             $spoilageLog = SpoilageLog::create([
113:                 'spoilage_number' => $spoilageNumber,
114:                 'pos_shift_id' => $posShift->id,
115:                 'spoilage_source' => $data->spoilageSource,
116:                 'service_id' => $data->serviceId,
117:                 'failed_output_qty' => $data->failedOutputQty,
118:                 'reason_category' => $data->reasonCategory->value,
119:                 'reason_description' => $data->reasonDescription,
120:                 'total_spoilage_cost' => $totalCost,
121:                 'reported_by_user_id' => $data->reportedByUserId,
122:                 'verified_by_user_id' => $data->verifiedByUserId,
123:                 'journal_entry_id' => null,
124:                 'logged_at' => Carbon::now(),
125:             ]);
126: 
127:             // Tulis spoilage_log_items dan stock_ledger_entries.
128:             foreach ($items as $item) {
129:                 SpoilageLogItem::create([
130:                     'spoilage_log_id' => $spoilageLog->id,
131:                     'product_id' => $item['product']->id,
132:                     'qty_wasted' => $item['qty_wasted'],
133:                     'unit_cost_at_spoilage' => $item['unit_cost'],
134:                     'subtotal_cost' => $item['subtotal'],
135:                 ]);
136: 
137:                 StockLedgerEntry::create([
138:                     'product_id' => $item['product']->id,
139:                     'pos_shift_id' => $posShift->id,
140:                     'reference_type' => 'SPOILAGE',
141:                     'reference_id' => $spoilageLog->id,
142:                     'qty_change' => '-' . $item['qty_wasted'],
143:                     'balance_before' => $item['balance_before'],
144:                     'balance_after' => $item['balance_after'],
145:                     'unit_cost' => $item['unit_cost'],
146:                     'total_value' => $item['subtotal'],
147:                     'created_by' => $data->reportedByUserId,
148:                     'created_at' => Carbon::now(),
149:                 ]);
150:             }
151: 
152:             // Posting jurnal: Dr. 6-1101 Beban Kerusakan Produksi Jasa, Cr. 1-1302 Persediaan Bahan Baku Jasa.
153:             $coaSpoilageExpense = ChartOfAccount::where('account_code', '6-1101')->lockForUpdate()->firstOrFail();
154:             $coaInventoryRaw = ChartOfAccount::where('account_code', '1-1302')->lockForUpdate()->firstOrFail();
155: 
156:             $period = app(\App\Models\AccountingPeriod::class)
157:                 ->where('is_closed', false)
158:                 ->orderBy('start_date', 'desc')
159:                 ->first();
160: 
161:             $journalData = new JournalEntryData(
162:                 journalNumber: 'JRN-' . Carbon::now()->format('Ymd') . '-' .
163:                     str_pad((string) (JournalEntry::count() + 1), 4, '0', STR_PAD_LEFT),
164:                 accountingPeriodId: (string) ($period?->getKey() ?? ''),
165:                 posShiftId: (string) $posShift->id,
166:                 entryDate: Carbon::now(),
167:                 journalType: JournalType::SPOILAGE,
168:                 referenceType: 'App\Models\SpoilageLog',
169:                 referenceId: $spoilageLog->id,
170:                 description: 'Barang rusak / gagal produksi: ' . $data->reasonDescription .
171:                     ' (total Rp ' . $totalCost . ')',
172:                 lines: [
173:                     new JournalLineData(
174:                         chartOfAccountCode: $coaSpoilageExpense->account_code,
175:                         debit: $totalCost,
176:                         credit: '0.0000',
177:                         lineDescription: 'Debit Beban Kerusakan / Kegagalan Produksi Jasa',
178:                     ),
179:                     new JournalLineData(
180:                         chartOfAccountCode: $coaInventoryRaw->account_code,
181:                         debit: '0.0000',
182:                         credit: $totalCost,
183:                         lineDescription: 'Kredit Persediaan Bahan Baku Jasa',
184:                     ),
185:                 ],
186:                 createdByUserId: $data->reportedByUserId,
187:             );
188: 
189:             $journalEntry = app(\App\Actions\Accounting\PostDoubleEntryJournalAction::class)
190:                 ->execute($journalData);
191: 
192:             $spoilageLog->update(['journal_entry_id' => $journalEntry->id]);
193: 
194:             return $spoilageLog->fresh(['items.product', 'journalEntry']);
195:         });
196:     }
