23:      * beserta tarif jual, pemetaan akun pendapatan, dan resep bahan baku (BoM).
24:      *
25:      * @param array{
26:      *     name: string,
27:      *     code?: ?string,
28:      *     category_id?: ?int,
29:      *     service_group: string,
30:      *     base_unit_name?: string,
31:      *     base_price: int|float|string,
32:      *     boms?: array<int, array{raw_material_product_id: int|string, consumption_qty: int|float|string}>,
33:      *     price_tiers?: array<int, array{tier_name: string, min_qty: int|float|string, discount_type?: string, discount_value: int|float|string}>
34:      * } $data
35:      */
36:     public function execute(array $data): Service
37:     {
38:         return DB::transaction(function () use ($data): Service {
39:             $serviceGroup = ServiceGroup::from($data['service_group']);
40:             $basePrice = number_format((float) ($data['base_price'] ?? 0), 4, '.', '');
41:             $baseUnit = trim((string) ($data['base_unit_name'] ?? 'Lembar')) ?: 'Lembar';
42: 
43:             // Kategori Layanan Jasa (category_scope = 'SERVICE' atau id yang disediakan)
44:             $categoryId = $data['category_id'] ?? null;
45:             if (!$categoryId) {
46:                 $category = Category::where('category_scope', 'SERVICE')->first()
47:                     ?? Category::where('slug', 'layanan-jasa')->firstOrFail();
48:                 $categoryId = $category->id;
49:             }
50: 
51:             // Pemetaan akun pendapatan & potongan berdasarkan grup jasa
52:             $revAccountCode = match ($serviceGroup) {
53:                 ServiceGroup::FOTOCOPY => '4-2101', // Pendapatan Jasa Fotocopy
54:                 ServiceGroup::PRINT => '4-2102',    // Pendapatan Jasa Print
55:                 ServiceGroup::LAMINATING, ServiceGroup::BINDING => '4-2103', // Pendapatan Jasa Laminating & Jilid
56:                 default => '4-2101',
57:             };
58: 
59:             $revenueCoa = ChartOfAccount::where('account_code', $revAccountCode)->firstOrFail();
60:             $discountCoa = ChartOfAccount::where('account_code', '4-2109')->firstOrFail(); // Potongan Pendapatan Jasa
61: 
62:             // Generate Kode Layanan jika kosong
63:             $code = trim((string) ($data['code'] ?? ''));
64:             if ($code === '') {
65:                 $prefix = match ($serviceGroup) {
66:                     ServiceGroup::FOTOCOPY => 'SRV-FC',
67:                     ServiceGroup::PRINT => 'SRV-PRT',
68:                     ServiceGroup::LAMINATING => 'SRV-LAM',
69:                     ServiceGroup::BINDING => 'SRV-BND',
70:                     ServiceGroup::SCAN => 'SRV-SCN',
71:                     default => 'SRV-OTH',
72:                 };
73:                 $slug = strtoupper((string) Str::slug(substr($data['name'], 0, 10)));
74:                 $slug = preg_replace('/[^A-Z0-9]/', '', $slug) ?: 'ITEM';
75:                 $code = "{$prefix}-{$slug}";
76:                 $baseCode = $code;
77:                 $counter = 1;
78:                 while (Service::where('code', $code)->exists()) {
79:                     $code = "{$baseCode}-{$counter}";
80:                     $counter++;
81:                 }
82:             } else {
83:                 if (Service::where('code', $code)->exists()) {
84:                     throw new InvalidArgumentException("Kode layanan {$code} sudah terdaftar.");
85:                 }
86:             }
87: 
88:             // Simpan master service
89:             $service = Service::create([
90:                 'code' => $code,
91:                 'name' => trim($data['name']),
92:                 'category_id' => $categoryId,
93:                 'service_group' => $serviceGroup,
94:                 'base_unit_name' => $baseUnit,
95:                 'base_price' => $basePrice,
96:                 'revenue_account_id' => $revenueCoa->id,
97:                 'discount_account_id' => $discountCoa->id,
98:                 'is_active' => true,
99:             ]);
100: 
101:             // Simpan Resep Bahan Baku (Bill of Materials) jika ada
102:             if (!empty($data['boms'])) {
103:                 foreach ($data['boms'] as $bomItem) {
104:                     $rawMaterialId = (int) $bomItem['raw_material_product_id'];
105:                     $consumptionQty = number_format((float) $bomItem['consumption_qty'], 4, '.', '');
106: 
107:                     if ($rawMaterialId > 0 && bccomp($consumptionQty, '0.0000', 4) > 0) {
108:                         $rawProd = Product::findOrFail($rawMaterialId);
109: 
110:                         ServiceBom::create([
111:                             'service_id' => $service->id,
112:                             'raw_material_product_id' => $rawProd->id,
113:                             'consumption_qty' => $consumptionQty,
114:                             'is_required' => true,
115:                             'notes' => "BoM untuk layanan {$service->name}",
116:                         ]);
117:                     }
118:                 }
119:             }
120: 
121:             // Simpan Tier Diskon Grosir jika ada
122:             if (!empty($data['price_tiers'])) {
123:                 $priority = 1;
124:                 foreach ($data['price_tiers'] as $tier) {
125:                     $minQty = number_format((float) ($tier['min_qty'] ?? 1), 4, '.', '');
126:                     $discVal = number_format((float) ($tier['discount_value'] ?? 0), 4, '.', '');
127:                     $tierType = isset($tier['discount_type'])
128:                         ? DiscountTierType::from($tier['discount_type'])
129:                         : DiscountTierType::SPECIAL_UNIT_PRICE;
130: 
131:                     if (bccomp($minQty, '0.0000', 4) > 0 && bccomp($discVal, '0.0000', 4) > 0) {
132:                         ServicePriceTier::create([
133:                             'service_id' => $service->id,
134:                             'tier_name' => trim($tier['tier_name'] ?? "Grosir \u{2265} " . rtrim(rtrim($minQty, '0'), '.') . " {$baseUnit}"),
135:                             'min_qty' => $minQty,
136:                             'max_qty' => !empty($tier['max_qty']) ? number_format((float) $tier['max_qty'], 4, '.', '') : null,
137:                             'discount_type' => $tierType,
138:                             'discount_value' => $discVal,
139:                             'priority' => $priority++,
140:                             'is_active' => true,
141:                         ]);
142:                     }
143:                 }
144:             }
145: 
146:             return $service->fresh(['category', 'revenueAccount', 'discountAccount', 'boms.rawMaterialProduct', 'priceTiers']);
147:         });
148:     }
