5: namespace App\Services\Pos;
6: 
7: use App\Enums\DiscountTierType;
8: use App\Models\Service;
9: use App\Models\ServicePriceTier;
10: 
11: final readonly class TieredPricingResolver
12: {
13:     /**
14:      * Menghitung harga satuan efektif dan potongan grosir otomatis untuk layanan jasa
15:      * (misal Fotocopy >= 100 lembar). Semua nilai dalam string dengan skala 4 desimal.
16:      *
17:      * @return array{
18:      *     applied_tier_id: int|null,
19:      *     base_unit_price: string,
20:      *     tier_discount_per_unit: string,
21:      *     final_unit_price: string,
22:      *     line_subtotal_gross: string,
23:      *     line_tier_discount_total: string,
24:      *     line_net_before_manual: string
25:      * }
26:      */
27:     public function resolve(Service $service, string $qty): array
28:     {
29:         $basePrice = number_format((float) $service->base_price, 4, '.', '');
30:         $normalizedQty = number_format((float) $qty, 4, '.', '');
31: 
32:         /** @var ServicePriceTier|null $matchedTier */
33:         $matchedTier = $service->priceTiers()
34:             ->where('is_active', true)
35:             ->where('min_qty', '<=', $normalizedQty)
36:             ->where(static function ($query) use ($normalizedQty): void {
37:                 $query->whereNull('max_qty')
38:                     ->orWhere('max_qty', '>=', $normalizedQty);
39:             })
40:             ->orderByDesc('min_qty')
41:             ->orderBy('priority')
42:             ->first();
43: 
44:         $discountPerUnit = '0.0000';
45: 
46:         if ($matchedTier !== null) {
47:             $tierVal = number_format((float) $matchedTier->discount_value, 4, '.', '');
48:             $discountType = $matchedTier->discount_type;
49: 
50:             $discountPerUnit = match ($discountType) {
51:                 DiscountTierType::PERCENTAGE => bcdiv(bcmul($basePrice, $tierVal, 6), '100.0000', 4),
52:                 DiscountTierType::FIXED_DISCOUNT_PER_UNIT => $tierVal,
53:                 DiscountTierType::SPECIAL_UNIT_PRICE => bccomp($basePrice, $tierVal, 4) === 1
54:                     ? bcsub($basePrice, $tierVal, 4)
55:                     : '0.0000',
56:             };
57:         }
58: 
59:         $finalUnitPrice = bcsub($basePrice, $discountPerUnit, 4);
60:         if (bccomp($finalUnitPrice, '0.0000', 4) === -1) {
61:             $finalUnitPrice = '0.0000';
62:             $discountPerUnit = $basePrice;
63:         }
64: 
65:         $grossSubtotal = bcmul($normalizedQty, $basePrice, 4);
66:         $tierDiscountTotal = bcmul($normalizedQty, $discountPerUnit, 4);
67:         $netTotal = bcsub($grossSubtotal, $tierDiscountTotal, 4);
68: 
69:         return [
70:             'applied_tier_id' => $matchedTier?->id,
71:             'base_unit_price' => $basePrice,
72:             'tier_discount_per_unit' => $discountPerUnit,
73:             'final_unit_price' => $finalUnitPrice,
74:             'line_subtotal_gross' => $grossSubtotal,
75:             'line_tier_discount_total' => $tierDiscountTotal,
76:             'line_net_before_manual' => $netTotal,
77:         ];
78:     }
79: }

