19: final class PostDoubleEntryJournalAction
20: {
21:     /**
22:      * Posting jurnal double-entry yang atomik dan immutable.
23:      *
24:      * @throws UnbalancedJournalException jika total debit != total credit atau total <= 0.
25:      */
26:     public function execute(JournalEntryData $data): JournalEntry
27:     {
28:         return DB::transaction(function () use ($data): JournalEntry {
29:             // Validasi periode akuntansi masih terbuka.
30:             $period = AccountingPeriod::where('id', $data->accountingPeriodId)
31:                 ->lockForUpdate()
32:                 ->firstOrFail();
33: 
34:             if ($period->is_closed) {
35:                 throw new \DomainException('Akuntansi periode sudah ditutup, tidak bisa posting jurnal.');
36:             }
37: 
38:             // Validasi keseimbangan jurnal menggunakan bcmath (scale 4).
39:             $totalDebit = '0.0000';
40:             $totalCredit = '0.0000';
41: 
42:             foreach ($data->lines as $line) {
43:                 $totalDebit = bcadd($totalDebit, $line->debit, 4);
44:                 $totalCredit = bcadd($totalCredit, $line->credit, 4);
45:             }
46: 
47:             if (bccomp($totalDebit, $totalCredit, 4) !== 0) {
48:                 throw new UnbalancedJournalException(
49:                     'Jurnal tidak seimbang: total debit ' . $totalDebit . ' != total kredit ' . $totalCredit . '.'
50:                 );
51:             }
52: 
53:             if (bccomp($totalDebit, '0.0000', 4) !== 1) {
54:                 throw new UnbalancedJournalException('Total debit jurnal harus lebih besar dari nol.');
55:             }
56: 
57:             // Lock semua akun yang terlibat untuk mencegah race condition.
58:             $accountCodes = array_unique(array_map(fn (JournalLineData $line): string => $line->chartOfAccountCode, $data->lines));
59:             $accounts = ChartOfAccount::whereIn('account_code', $accountCodes)
60:                 ->lockForUpdate()
61:                 ->get()
62:                 ->keyBy('account_code');
63: 
64:             // Persist journal_entries.
65:             $journalEntry = JournalEntry::create([
66:                 'journal_number' => $data->journalNumber,
67:                 'accounting_period_id' => $data->accountingPeriodId,
68:                 'pos_shift_id' => $data->posShiftId,
69:                 'entry_date' => $data->entryDate->format('Y-m-d'),
70:                 'journal_type' => $data->journalType->value,
71:                 'reference_type' => $data->referenceType,
72:                 'reference_id' => $data->referenceId,
73:                 'description' => $data->description,
74:                 'total_debit' => $totalDebit,
75:                 'total_credit' => $totalCredit,
76:                 'is_posted' => true,
77:                 'is_reversed' => false,
78:                 'reversed_by_journal_id' => $data->reversedByJournalId,
79:                 'created_by_user_id' => $data->createdByUserId,
80:                 'posted_at' => Carbon::now(),
81:             ]);
82: 
83:             // Persist journal_items dan update saldo akun.
84:             foreach ($data->lines as $line) {
85:                 $account = $accounts->get($line->chartOfAccountCode);
86:                 if (!$account) {
87:                     throw new \DomainException('Chart of Account dengan kode ' . $line->chartOfAccountCode . ' tidak ditemukan.');
88:                 }
89: 
90:                 JournalItem::create([
91:                     'journal_entry_id' => $journalEntry->id,
92:                     'chart_of_account_id' => $account->id,
93:                     'line_description' => $line->lineDescription,
94:                     'debit' => $line->debit,
95:                     'credit' => $line->credit,
96:                 ]);
97: 
98:                 // Update current_balance berdasarkan normal_balance.
99:                 $this->updateAccountBalance($account, $line->debit, $line->credit);
100:             }
101: 
102:             // Untuk setiap baris yang menyentuh akun CASH_BANK, catat otomatis ke Buku Kas Umum.
103:             // RecordCashBookEntryAction akan dipanggil oleh pemanggil untuk transaksi POS,
104:             // namun di sini kita memastikan BKU tercantum untuk jurnal kas umum.
105:             $this->recordCashBookEntries($journalEntry, $data);
106: 
107:             return $journalEntry->load('items.chartOfAccount');
108:         });
109:     }
110: 
111:     /**
112:      * Update saldo aktual chart_of_accounts berdasarkan normal balance.
113:      */
114:     private function updateAccountBalance(ChartOfAccount $account, string $debit, string $credit): void
115:     {
116:         $current = (string) $account->current_balance;
117:         $newBalance = $current;
118: 
119:         if ($account->normal_balance === NormalBalance::DEBIT) {
120:             // Saldo debit bertambah dengan debit, berkurang dengan kredit.
121:             $newBalance = bcadd($current, $debit, 4);
122:             $newBalance = bcsub($newBalance, $credit, 4);
123:         } else {
124:             // Saldo kredit bertambah dengan kredit, berkurang dengan debit.
125:             $newBalance = bcadd($current, $credit, 4);
126:             $newBalance = bcsub($newBalance, $debit, 4);
127:         }
128: 
129:         $account->update(['current_balance' => $newBalance]);
130:     }
131: 
132:     /**
133:      * Catat entri Buku Kas Umum untuk baris jurnal yang menyentuh akun kas/bank.
134:      */
135:     private function recordCashBookEntries(JournalEntry $journalEntry, JournalEntryData $data): void
136:     {
137:         $cashBookService = app(\App\Actions\Accounting\RecordCashBookEntryAction::class);
138: 
139:         foreach ($journalEntry->items as $item) {
140:             $account = $item->chartOfAccount;
141:             if (!$account->isCashBank()) {
142:                 continue;
143:             }
144: 
145:             $debit = $item->debit;
146:             $credit = $item->credit;
147: 
148:             $cashBookService->execute(
149:                 journalEntryId: (string) $journalEntry->id,
150:                 posShiftId: $data->posShiftId,
151:                 cashAccountId: (string) $account->id,
152:                 transactionDate: $data->entryDate,
153:                 mutationDirection: $debit !== '0.0000' ? 'IN' : 'OUT',
154:                 category: $journalEntry->journal_type instanceof \BackedEnum ? $journalEntry->journal_type->value : (string) $journalEntry->journal_type,
155:                 description: $journalEntry->description . ' (BKU otomatis dari ' . $journalEntry->journal_number . ')',
156:                 debitIn: $debit,
157:                 creditOut: $credit,
158:                 recordedByUserId: $data->createdByUserId,
159:             );
160:         }
161:     }
162: }

