20: final class RecordBatchPurchaseInboundAction
21: {
22:     /**
23:      * Catat barang masuk / restock multi-produk secara batch dalam satu transaksi atomik.
24:      * Mengupdate stok & HPP setiap produk, mencatat buku besar persediaan (StockLedgerEntry),
25:      * dan memposting jurnal ganda yang seimbang ke kas / utang usaha.
26:      *
27:      * @param array<int, array{product_id: int|string, qty: int|float|string, price: int|float|string}> $items
28:      * @return array{journal_entry: JournalEntry, total_amount: string, items_count: int, processed_products: array}
29:      */
30:     public function execute(
31:         array $items,
32:         string $accountId,
33:         string $createdByUserId,
34:         ?string $invoiceNumber = null,
35:         ?string $notes = null,
36:     ): array {
37:         if (empty($items)) {
38:             throw new InvalidArgumentException('Daftar barang masuk tidak boleh kosong.');
39:         }
40: 
41:         return DB::transaction(function () use (
42:             $items,
43:             $accountId,
44:             $createdByUserId,
45:             $invoiceNumber,
46:             $notes
47:         ): array {
48:             $coaCashOrDebt = ChartOfAccount::where('id', $accountId)->lockForUpdate()->firstOrFail();
49: 
50:             $period = AccountingPeriod::where('is_closed', false)
51:                 ->orderBy('start_date', 'desc')
52:                 ->first();
53: 
54:             $productIds = array_unique(array_column($items, 'product_id'));
55:             $products = Product::with(['unit', 'inventoryAccount'])
56:                 ->whereIn('id', $productIds)
57:                 ->lockForUpdate()
58:                 ->get()
59:                 ->keyBy('id');
60: 
61:             $totalInvoiceAmount = '0.0000';
62:             $journalLines = [];
63:             $ledgerEntriesToCreate = [];
64:             $processedProducts = [];
65: 
66:             foreach ($items as $itemData) {
67:                 $productId = (int) $itemData['product_id'];
68:                 /** @var Product|null $product */
69:                 $product = $products->get($productId);
70: 
71:                 if (!$product) {
72:                     throw new InvalidArgumentException("Produk dengan ID {$productId} tidak ditemukan.");
73:                 }
74: 
75:                 $qty = number_format((float) $itemData['qty'], 4, '.', '');
76:                 $price = number_format((float) $itemData['price'], 4, '.', '');
77: 
78:                 if (bccomp($qty, '0.0000', 4) <= 0) {
79:                     throw new InvalidArgumentException("Kuantitas untuk produk {$product->name} harus lebih dari 0.");
80:                 }
81:                 if (bccomp($price, '0.0000', 4) < 0) {
82:                     throw new InvalidArgumentException("Harga beli untuk produk {$product->name} tidak boleh negatif.");
83:                 }
84: 
85:                 $lineSubtotal = bcmul($qty, $price, 4);
86:                 $totalInvoiceAmount = bcadd($totalInvoiceAmount, $lineSubtotal, 4);
87: 
88:                 $oldStock = (string) $product->current_stock;
89:                 $oldAvgCost = (string) $product->average_cost;
90:                 $newStock = bcadd($oldStock, $qty, 4);
91: 
92:                 $newAvgCost = bccomp($newStock, '0.0000', 4) > 0
93:                     ? bcdiv(
94:                         bcadd(bcmul($oldStock, $oldAvgCost, 4), bcmul($qty, $price, 4), 4),
95:                         $newStock,
96:                         4
97:                     )
98:                     : $price;
99: 
100:                 $product->update([
101:                     'current_stock' => $newStock,
102:                     'average_cost' => $newAvgCost,
103:                     'last_purchase_price' => $price,
104:                 ]);
105: 
106:                 $unitCode = $product->unit ? $product->unit->code : 'UNIT';
107:                 $formattedQty = rtrim(rtrim($qty, '0'), '.');
108:                 $formattedPrice = number_format((float) $price, 0, ',', '.');
109: 
110:                 // Siapkan baris jurnal debit untuk akun persediaan produk
111:                 $journalLines[] = new JournalLineData(
112:                     chartOfAccountCode: $product->inventoryAccount->account_code,
113:                     debit: $lineSubtotal,
114:                     credit: '0.0000',
115:                     lineDescription: "Masuk {$product->name} ({$formattedQty} {$unitCode} @ Rp {$formattedPrice})",
116:                 );
117: 
118:                 $ledgerEntriesToCreate[] = [
119:                     'product_id' => $product->id,
120:                     'pos_shift_id' => null,
121:                     'reference_type' => 'PURCHASE',
122:                     'qty_change' => $qty,
123:                     'balance_before' => $oldStock,
124:                     'balance_after' => $newStock,
125:                     'unit_cost' => $price,
126:                     'total_value' => $lineSubtotal,
127:                     'created_by' => $createdByUserId,
128:                     'created_at' => Carbon::now(),
129:                 ];
130: 
131:                 $processedProducts[] = [
132:                     'product' => $product->fresh(),
133:                     'qty' => $qty,
134:                     'unit_cost' => $price,
135:                     'subtotal' => $lineSubtotal,
136:                     'new_stock' => $newStock,
137:                     'new_average_cost' => $newAvgCost,
138:                 ];
139:             }
140: 
141:             // Tambahkan baris kredit tunggal untuk sumber dana (Kas Besar / Utang Usaha)
142:             $invLabel = $invoiceNumber ? " [Faktur: {$invoiceNumber}]" : '';
143:             $journalLines[] = new JournalLineData(
144:                 chartOfAccountCode: $coaCashOrDebt->account_code,
145:                 debit: '0.0000',
146:                 credit: $totalInvoiceAmount,
147:                 lineDescription: "Kredit {$coaCashOrDebt->account_name}{$invLabel}",
148:             );
149: 
150:             $journalCount = JournalEntry::count() + 1;
151:             $journalNumber = 'JRN-' . Carbon::now()->format('Ymd') . '-' . str_pad((string) $journalCount, 4, '0', STR_PAD_LEFT);
152: 
153:             $descParts = [
154:                 'Barang Masuk Multi-item (' . count($items) . ' produk)',
155:             ];
156:             if ($invoiceNumber) {
157:                 $descParts[] = "Faktur: {$invoiceNumber}";
158:             }
159:             if ($notes) {
160:                 $descParts[] = $notes;
161:             }
162:             $description = implode(' | ', $descParts);
163: 
164:             $journalData = new JournalEntryData(
165:                 journalNumber: $journalNumber,
166:                 accountingPeriodId: (string) ($period?->getKey() ?? ''),
167:                 posShiftId: null,
168:                 entryDate: Carbon::now(),
169:                 journalType: JournalType::PURCHASE,
170:                 referenceType: 'BATCH_PURCHASE',
171:                 referenceId: null,
172:                 description: $description,
173:                 lines: $journalLines,
174:                 createdByUserId: (string) $createdByUserId,
175:             );
176: 
177:             /** @var JournalEntry $journalEntry */
178:             $journalEntry = app(PostDoubleEntryJournalAction::class)->execute($journalData);
179: 
180:             // Simpan data kartu stok ledger dengan referensi ke id jurnal
181:             foreach ($ledgerEntriesToCreate as $ledgerData) {
182:                 $ledgerData['reference_id'] = $journalEntry->id;
183:                 StockLedgerEntry::create($ledgerData);
184:             }
185: 
186:             return [
187:                 'journal_entry' => $journalEntry,
188:                 'total_amount' => $totalInvoiceAmount,
189:                 'items_count' => count($items),
190:                 'processed_products' => $processedProducts,
191:             ];
192:         });
193:     }
194: }
