138:     protected function isValidNumericFormat(string $value): bool
139:     {
140:         // Pattern dasar: optional minus, angka, optional desimal
141:         $pattern = $this->allowNegative ? '/^-?\d+(\.\d+)?$/' : '/^\d+(\.\d+)?$/';
142:         
143:         // Untuk integer only
144:         if (!$this->allowDecimal) {
145:             $pattern = $this->allowNegative ? '/^-?\d+$/' : '/^\d+$/';
