157:         // Tidak boleh leading zeros (kecuali 0 atau 0.x)
158:         if (preg_match('/^0\d+/', $value)) {
159:             return false;
160:         }
161: 
162:         // Pastikan bisa di-cast ke numeric tanpa error
163:         if (!is_numeric($value)) {
164:             return false;
165:         }
166: 
167:         return true;
168:     }
