27:      * @param array<int, array{product_id: int|string, qty: int|float|string, price: int|float|string}> $items
28:      * @return array{journal_entry: JournalEntry, total_amount: string, items_count: int, processed_products: array}
29:      */
30:     public function execute(
31:         array $items,
32:         string $accountId,
33:         string $createdByUserId,
34:         ?string $invoiceNumber = null,
35:         ?string $notes = null,
36:     ): array {
37:         if (empty($items)) {
38:             throw new InvalidArgumentException('Daftar barang masuk tidak boleh kosong.');
39:         }
40: 
41:         return DB::transaction(function () use (
42:             $items,
43:             $accountId,
44:             $createdByUserId,
45:             $invoiceNumber,
46:             $notes
47:         ): array {
48:             $coaCashOrDebt = ChartOfAccount::where('id', $accountId)->lockForUpdate()->firstOrFail();
49: 
50:             $period = AccountingPeriod::where('is_closed', false)
51:                 ->orderBy('start_date', 'desc')
52:                 ->first();
53: 
54:             $productIds = array_unique(array_column($items, 'product_id'));
55:             $products = Product::with(['unit', 'inventoryAccount'])
56:                 ->whereIn('id', $productIds)
57:                 ->lockForUpdate()
58:                 ->get()
59:                 ->keyBy('id');
60: 
61:             $totalInvoiceAmount = '0.0000';
62:             $journalLines = [];
63:             $ledgerEntriesToCreate = [];
64:             $processedProducts = [];
65: 
66:             foreach ($items as $itemData) {
67:                 $productId = (int) $itemData['product_id'];
68:                 /** @var Product|null $product */
69:                 $product = $products->get($productId);
70: 
71:                 if (!$product) {
72:                     throw new InvalidArgumentException("Produk dengan ID {$productId} tidak ditemukan.");
73:                 }
74: 
75:                 $qty = number_format((float) $itemData['qty'], 4, '.', '');
76:                 $price = number_format((float) $itemData['price'], 4, '.', '');
77: 
78:                 if (bccomp($qty, '0.0000', 4) <= 0) {
79:                     throw new InvalidArgumentException("Kuantitas untuk produk {$product->name} harus lebih dari 0.");
80:                 }
81:                 if (bccomp($price, '0.0000', 4) < 0) {
82:                     throw new InvalidArgumentException("Harga beli untuk produk {$product->name} tidak boleh negatif.");
83:                 }
84: 
85:                 $lineSubtotal = bcmul($qty, $price, 4);
