111:                 $journalLines[] = new JournalLineData(
112:                     chartOfAccountCode: $product->inventoryAccount->account_code,
113:                     debit: $lineSubtotal,
114:                     credit: '0.0000',
115:                     lineDescription: "Masuk {$product->name} ({$formattedQty} {$unitCode} @ Rp {$formattedPrice})",
116:                 );
117: 
118:                 $ledgerEntriesToCreate[] = [
119:                     'product_id' => $product->id,
120:                     'pos_shift_id' => null,
121:                     'reference_type' => 'PURCHASE',
122:                     'qty_change' => $qty,
123:                     'balance_before' => $oldStock,
124:                     'balance_after' => $newStock,
125:                     'unit_cost' => $price,
126:                     'total_value' => $lineSubtotal,
127:                     'created_by' => $createdByUserId,
128:                     'created_at' => Carbon::now(),
129:                 ];
130: 
131:                 $processedProducts[] = [
132:                     'product' => $product->fresh(),
133:                     'qty' => $qty,
