10: final class MovingAverageCostCalculator
11: {
12:     /**
13:      * Hitung Moving Average Cost baru setelah penambahan stok.
14:      *
15:      * Rumus: ((Old Stock * Old Avg Cost) + (Added Qty * Added Unit Cost)) / (Old Stock + Added Qty)
16:      */
17:     public function calculate(Product $product, string $addedQty, string $addedUnitCost): string
18:     {
19:         $oldStock = (string) $product->current_stock;
20:         $oldAvgCost = (string) $product->average_cost;
21: 
22:         $oldValue = bcmul($oldStock, $oldAvgCost, 4);
23:         $addedValue = bcmul($addedQty, $addedUnitCost, 4);
24:         $newStock = bcadd($oldStock, $addedQty, 4);
25: 
26:         if (bccomp($newStock, '0.0000', 4) === 0) {
27:             return '0.0000';
28:         }
29: 
30:         return bcdiv(bcadd($oldValue, $addedValue, 4), $newStock, 4);
31:     }
32: 
33:     /**
34:      * Hitung total nilai stok saat ini berdasarkan Moving Average Cost.
35:      */
36:     public function totalStockValue(Product $product): string
37:     {
38:         return bcmul((string) $product->current_stock, (string) $product->average_cost, 4);
39:     }
