299:     private function rules(Request $request, ?User $user): array
300:     {
301:         $actor = $request->user();
302:         $allowedRoles = array_map(
303:             static fn (UserRole $role): string => $role->value,
304:             $this->assignableRoles($actor, $user)
305:         );
306:         $studentProfile = $user?->studentProfile;
307:         $requestedRole = (string) $request->input('role_type');
308:         $isStudent = $requestedRole === UserRole::PIKET_SISWA->value;
309:         $requiresPin = in_array($requestedRole, [
310:             UserRole::SUPERADMIN->value,
311:             UserRole::ADMIN->value,
312:             UserRole::PIKET_GURU->value,
313:         ], true);
314:         $pinRequired = $requiresPin && ($user === null || $user->pin_code === null);
315: 
316:         return [
317:             'name' => ['required', 'string', 'max:150'],
318:             'username' => [
319:                 'required',
320:                 'string',
321:                 'max:50',
322:                 'regex:/^[A-Za-z0-9_.-]+$/',
323:                 Rule::unique('users', 'username')->ignore($user?->id),
324:             ],
325:             'email' => [
326:                 'nullable',
327:                 'email',
328:                 'max:150',
329:                 Rule::unique('users', 'email')->ignore($user?->id),
330:             ],
331:             'nip_nisn' => [
332:                 'nullable',
333:                 'string',
334:                 'max:30',
335:                 'regex:/^[A-Za-z0-9_.-]*$/',
336:                 Rule::unique('users', 'nip_nisn')->ignore($user?->id),
337:             ],
338:             'role_type' => ['required', Rule::in($allowedRoles)],
339:             'is_active' => ['nullable', 'boolean'],
340:             'password' => $user
341:                 ? ['nullable', 'string', 'min:8', 'confirmed']
342:                 : ['required', 'string', 'min:8', 'confirmed'],
343:             'pin_code' => ['nullable', 'digits:6', Rule::requiredIf($pinRequired)],
344:             'school_class_id' => [
345:                 'nullable',
346:                 'exists:school_classes,id',
347:                 Rule::requiredIf($isStudent),
348:             ],
349:             'nis' => [
350:                 'nullable',
351:                 'string',
352:                 'max:25',
353:                 Rule::requiredIf($isStudent),
354:                 Rule::unique('student_profiles', 'nis')->ignore($studentProfile?->id),
355:             ],
356:             'phone' => ['nullable', 'string', 'max:20', 'regex:/^[0-9+()\s-]*$/'],
357:         ];
358:     }
