362:      *
363:      * Akun sendiri selalu mempertahankan role-nya agar superadmin tidak
364:      * kehilangan akses, dan superadmin tidak dapat membuat superadmin baru.
365:      *
366:      * @return array<int, UserRole>
367:      */
368:     private function assignableRoles(User $actor, ?User $target = null): array
369:     {
370:         if ($target !== null && $target->is($actor)) {
371:             return [$actor->role_type];
372:         }
373: 
374:         return $actor->role_type->assignableRoles();
375:     }
