278:                     $this->cart[$key]['subtotal_gross'] = (float) $pricing['line_subtotal_gross'];
279:                     $this->cart[$key]['subtotal_net'] = (float) bcsub($pricing['line_net_before_manual'], $manualDiscount, 4);
280:                 }
281:             } else {
282:                 $gross = bcmul($qty, (string) $item['base_price'], 4);
283:                 $net = bcsub($gross, $manualDiscount, 4);
