601:     private function normalizeQuantity(string $value): string
602:     {
603:         $value = trim($value);
604: 
605:         if ($value === '' || ! preg_match('/^\d+(\.\d{1,4})?$/', $value)) {
606:             throw new \DomainException('Kuantitas item tidak valid.');
607:         }
608: 
609:         $normalized = number_format((float) $value, 4, '.', '');
610: 
611:         if (bccomp($normalized, '0.0000', 4) !== 1) {
612:             throw new \DomainException('Kuantitas item harus lebih besar dari nol.');
613:         }
614: 
615:         return $normalized;
616:     }
