16: final class CreateReversingJournalAction
17: {
18:     /**
19:      * Buat jurnal pembalik (reversing journal) untuk koreksi immutable.
20:      * Setiap baris debit/kredit asli dibalik, dan jurnal asli ditandai is_reversed.
21:      */
22:     public function execute(JournalEntry $originalJournal, string $reversingJournalNumber, User $createdBy): JournalEntry
23:     {
24:         return DB::transaction(function () use ($originalJournal, $reversingJournalNumber, $createdBy): JournalEntry {
25:             $originalJournal = JournalEntry::whereKey($originalJournal->getKey())
26:                 ->lockForUpdate()
27:                 ->firstOrFail();
28: 
29:             if ($originalJournal->is_reversed) {
30:                 throw new \DomainException('Jurnal ini sudah pernah dibalik.');
31:             }
32: 
33:             // Jurnal pembalik harus masuk ke periode yang masih terbuka. Jika
34:             // periode asal sudah ditutup, gunakan periode terbuka terbaru agar
35:             // koreksi tidak mengubah laporan periode yang sudah final.
36:             $period = $originalJournal->accountingPeriod;
37: 
38:             if ($period === null || $period->is_closed) {
39:                 $period = AccountingPeriod::where('is_closed', false)
40:                     ->orderBy('start_date', 'desc')
41:                     ->lockForUpdate()
42:                     ->first();
43:             }
44: 
45:             if ($period === null) {
46:                 throw new \DomainException('Tidak ada periode akuntansi terbuka untuk jurnal pembalik.');
47:             }
48: 
49:             // Tandai jurnal asli sebagai reversed.
50:             $originalJournal->update(['is_reversed' => true]);
51: 
52:             // Buat baris jurnal pembalik: debit menjadi kredit dan sebaliknya.
53:             $lines = [];
54:             $totalDebit = '0.0000';
55:             $totalCredit = '0.0000';
56: 
57:             foreach ($originalJournal->items as $item) {
58:                 $reversedDebit = $item->credit;
59:                 $reversedCredit = $item->debit;
60: 
61:                 $totalDebit = bcadd($totalDebit, $reversedDebit, 4);
62:                 $totalCredit = bcadd($totalCredit, $reversedCredit, 4);
63: 
64:                 $lines[] = new JournalLineData(
65:                     chartOfAccountCode: $item->chartOfAccount->account_code,
66:                     debit: $reversedDebit,
67:                     credit: $reversedCredit,
68:                     lineDescription: 'REVERSING: ' . ($item->line_description ?? $originalJournal->description),
69:                 );
70:             }
71: 
72:             $data = new JournalEntryData(
73:                 journalNumber: $reversingJournalNumber,
74:                 accountingPeriodId: (string) $period->id,
75:                 posShiftId: $originalJournal->pos_shift_id ? (string) $originalJournal->pos_shift_id : null,
76:                 entryDate: Carbon::now(),
77:                 journalType: JournalType::REVERSING,
78:                 referenceType: $originalJournal->reference_type,
79:                 referenceId: $originalJournal->reference_id,
80:                 description: 'Pembalikan jurnal ' . $originalJournal->journal_number . ': ' . $originalJournal->description,
81:                 lines: $lines,
82:                 createdByUserId: (string) $createdBy->getKey(),
83:                 reversedByJournalId: null,
84:             );
85: 
86:             $action = app(PostDoubleEntryJournalAction::class);
87:             $reversingEntry = $action->execute($data);
88: 
89:             // Tandai reversing journal id pada jurnal asli (referensi balik).
90:             $originalJournal->update(['reversed_by_journal_id' => $reversingEntry->id]);
91: 
92:             return $reversingEntry->load('items.chartOfAccount');
93:         });
94:     }
